mapper.update:
UPDATE chatbot_daily_usage
SET request_count = request_count + 1
WHERE user_id = #{userId}
AND usage_date = #{usageDate}
AND request_count < #{dailyLimit}

mapper.select:
SELECT request_count
FROM chatbot_daily_usage
WHERE user_id = #{userId}
AND usage_date = #{usageDate}

mapper.update:
UPDATE chatbot_daily_usage u
JOIN chatbot_messages m
ON m.message_id = #{questionId}
JOIN chatbot_conversations c
ON c.conversation_id = m.conversation_id
SET u.request_count = u.request_count - 1
WHERE c.user_id = #{userId}
AND c.conversation_id = #{conversationId}
AND m.role = 'USER'
AND m.processing_status = 'FAILED'
AND u.user_id = #{userId}
AND u.usage_date = DATE(m.created_at)
AND u.request_count > 0
